from math12_native_geometry import geometry,path
FIGURE_PDF_CROPS=[(152,'ode296-maple-output',(1023,784,1256,983))]
def circles():
 def pt(x,y):return(245+40*x,220-40*y)
 paths=[path([pt(-4.5,0),pt(4.8,0)]),path([pt(0,-4.6),pt(0,4.8)])]
 for r in [3]:paths.append(path([pt(r*math.cos(i*math.pi/90),r*math.sin(i*math.pi/90)) for i in range(181)]))
 for m in [1,-1]:paths.append(path([pt(-4,-4*m),pt(4,4*m)],stroke='#0369a1'))
 a=3/math.sqrt(2);p=pt(a,a);paths.append(path([pt(a-1.3,a+1.3),pt(a+1.3,a-1.3)],stroke='#b91c1c'));labels=[(442,228,'x'),(247,20,'y'),(226,241,'O'),(361,101,'C=1'),(157,59,'c=9'),(344,174,'tangent'),(325,203,'radius')]
 paths.append(path([pt(a-.25,a+.25),pt(a,a+.5),pt(a+.25,a+.25)],stroke='#b91c1c'))
 for v in [-4,-3,-2,-1,1,2,3,4]:
  x,y=pt(v,0);paths.append(path([(x,y-3),(x,y+3)]));labels.append((x-5,y+22,str(v)))
  x,y=pt(0,v);paths.append(path([(x-3,y),(x+3,y)]));labels.append((x-23,y+5,str(v)))
 return geometry('Figure 10.3','Figure 10.3 — circle x²+y²=9 crossed orthogonally by radial lines; radius perpendicular to circle tangent',paths,labels,points=[{'x':p[0],'y':p[1]}],size=(500,435))
PAGES=[page('152_page_2.jpg',296,[heading('Example 12'),paragraph('Determine the orthogonal trajectories of the family of curves (circles) x²+y²=c.'),heading('Solution'),paragraph('To determine the orthogonal trajectories, determine the slope (derivative) of the family of circles with respect to x:'),eq(r'x^2+y^2=c\quad\Rightarrow\quad2x+2y\frac{dy}{dx}=0'),eq(r'\left(\frac{dy}{dx}\right)_F=-\frac{x}{y}','ii'),paragraph('Use the circle slope to obtain the other family of curves G of orthogonal trajectories:'),eq(r'\left(\frac{dy}{dx}\right)_G=-\frac1{\left(\frac{dy}{dx}\right)_F}'),eq(r'\frac{dy}{dx}=-\frac1{-x/y}=\frac{y}{x}\quad\Rightarrow\quad\frac{dy}{y}=\frac{dx}{x},\quad\mathrm{SDE}\quad\Rightarrow\quad\int\frac{dy}{y}=\int\frac{dx}{x}'),eq(r'\ln y=\ln x+\ln C\quad\Rightarrow\quad y=Cx','iii'),paragraph('Thus the family G represents a family of homogeneous straight lines passing through the origin. This is the result expected since the radii of a circle are homogeneous lines y=Cx, C any real number, perpendicular to the lines tangent to a circle.'),circles(),note('Nondegenerate real circles require c>0; c=0 is a single point and has no regular circle tangent. Use ln|y| and ln|x| on nonzero branches, and retain y=0 when dividing by y. The full orthogonal family also contains the vertical radial line x=0, which is not of the finite-slope form y=Cx. A division-free description is αx+βy=0, (α,β)≠(0,0). At a point (x,y)≠(0,0), the radial tangent vector (x,y) has zero dot product with the circle tangent (−y,x).'),heading('10.4.2 MAPLE graphic commands to view the graphs of given family of curves and its orthogonal trajectories'),paragraph('The general solution y(x)=sqrt[−x²+c₁] of Example 12 is the first family of curves. This can also be written as x²+y²=c. The orthogonal trajectories of the first family form the second family represented by y=Cx. View these by typing MAPLE commands:'),command('?conturplot'),command('with(plots):'),command('F := contourplot(x^2+y^2, x=-5..5, y=-5..5)', 'F := PLOT(...)',1),command('G := plot({seq(c*x, c=-5..5)}, x=-5..5, y=-5..5):'),command('display({F, G});'),figure('ode296-maple-output','Source MAPLE graph — circles and radial lines','Original software output showing concentric level curves and lines through the origin.'),note('The source help query is printed ?conturplot; the plotting command itself spells contourplot. The square-root expression gives only the upper semicircle: the circle has branches y=±√(c−x²). The first command plots level sets of x²+y²; exact level radii are not specified by the printed commands. The source software output is retained rather than inventing exact contour values. The seq command samples integer slopes −5 through 5 and omits the vertical line; it illustrates, rather than exhausts, the orthogonal family. These are transcribed source commands and output, not commands executed in SpaceBook.')])]
PAGES[0].update(title='DIFFERENTIAL EQUATIONS',visualStatus='Native circle/tangent/radius construction, exact source software output and all Maple commands',alternateVerification={'pdf':'Math Book for 12 class KPTBB.pdf','pdfPage':152,'side':'right','reason':'Full circle derivative, orthogonal reciprocal and enlarged software commands visually checked'})
EXAMPLES=[{'num':'12','title':'Orthogonal Trajectories','question':'Find orthogonal trajectories of x²+y²=c.','steps':['Take c>0 for regular circles and differentiate with c constant: 2x+2yy′=0.','Where y≠0, circle slope is −x/y. The perpendicular slope is y/x where x≠0.','Solve y′=y/x. For x,y≠0, separate dy/y=dx/x and integrate ln|y|=ln|x|+K.','Hence y=Cx for every nonzero real C. Also retain y=0, omitted by division, as C=0.','The vertical line x=0 is another radial trajectory omitted by the finite-slope representation.','Thus all lines through the origin, αx+βy=0 with nonzero coefficient pair, are the complete radial family.','At each regular intersection, radial vector (x,y) and circle tangent (−y,x) have dot product −xy+xy=0, proving perpendicularity without slope exceptions.'],'answer':'All radial lines through the origin: y=Cx plus x=0, equivalently αx+βy=0 with (α,β)≠(0,0).','sourceQuestionBlocks':[circles()],'progressiveSolution':True,'solutionOrigin':'SpaceBook learning enhancement','sourceReferences':[{'page':296,'jpg':'152_page_2.jpg','verification':'Circle slope, integration and source graph checked'}]}]
